package source

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Registry is the set of source kinds harnaas can resolve, keyed by the name a
// manifest writes.
//
// It exists so that adding a kind is additive: the install flow asks the
// registry for a resolver and hands it a request, and contains no branch on
// which kind it got. A registry value rather than one package-level map is what
// lets a test exercise dispatch — including the failure for a kind nobody
// registered — without reaching into the set the binary itself ships.
type Registry struct {
	mu sync.Mutex

	// kinds holds each kind's constructor rather than a kind, because a kind is
	// per run. See [Kind].
	kinds map[manifest.SourceKind]NewKind
}

// Default is the registry the kinds shipped with this binary register into, and
// the one the install flow resolves through. A kind package registers itself
// from its own init, so a kind that has been linked in is a kind that works.
var Default = &Registry{}

// Register adds a kind to [Default].
func Register(name manifest.SourceKind, newKind NewKind) {
	Default.Register(name, newKind)
}

// Register adds a kind under the name a manifest writes for it.
//
// A second registration of the same name panics rather than replacing or
// ignoring the first. Registration happens during package initialization, before
// the process has read anything, so the only way to reach it is a mistake in
// harnaas's own wiring — and the two silent outcomes are a binary that resolves
// through whichever kind happened to be linked last.
func (r *Registry) Register(name manifest.SourceKind, newKind NewKind) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if r.kinds == nil {
		r.kinds = make(map[manifest.SourceKind]NewKind)
	}
	if _, registered := r.kinds[name]; registered {
		panic(fmt.Sprintf("source: kind %q is registered twice", name))
	}
	r.kinds[name] = newKind
}

// Kinds returns every registered kind name, sorted.
//
// Sorted rather than in registration order, because registration order is
// whatever the import graph happens to produce and this list is rendered into
// the error a user reads when their kind is not among them.
func (r *Registry) Kinds() []manifest.SourceKind {
	r.mu.Lock()
	defer r.mu.Unlock()

	return r.kindNamesLocked()
}

// NewResolver constructs one resolver per registered kind and returns the
// [Resolver] that dispatches to them, which is the unit of one install run.
//
// The options are the run's, so they are settled once here rather than at each
// kind's own entry point: a caller cannot hand one kind a cache and forget to
// hand it to the next.
func (r *Registry) NewResolver(opts RunOptions) *Resolver {
	r.mu.Lock()
	defer r.mu.Unlock()

	kinds := make(map[manifest.SourceKind]Kind, len(r.kinds))
	for name, newKind := range r.kinds {
		kinds[name] = newKind(opts)
	}
	return &Resolver{kinds: kinds, registered: r.kindNamesLocked()}
}

// kindNamesLocked returns the registered names in sorted order. The caller holds
// the lock.
func (r *Registry) kindNamesLocked() []manifest.SourceKind {
	names := make([]manifest.SourceKind, 0, len(r.kinds))
	for name := range r.kinds {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// Resolver resolves every source of one install run.
//
// It holds one live kind per registered name, so the per-run state a kind keeps
// — chiefly which repository archives it has already fetched — lives exactly as
// long as the run that built it.
type Resolver struct {
	kinds map[manifest.SourceKind]Kind

	// registered is the sorted name list, captured at construction so the error
	// for an unsupported kind lists what this run could have resolved rather
	// than what the registry holds by the time somebody reads the message.
	registered []manifest.SourceKind
}

// Resolve resolves one asset's source through the kind that owns it.
//
// The lookup happens before the kind is asked to do anything, which is what
// makes "an unsupported kind reaches no network and writes no file" a property
// of the dispatch rather than a rule each kind has to honour on its way in.
func (r *Resolver) Resolve(ctx context.Context, req Request) (*Resolved, error) {
	name := req.Kind()

	kind, registered := r.kinds[name]
	if !registered {
		return nil, &UnsupportedKindError{Kind: name, Registered: slices.Clone(r.registered)}
	}

	return kind.Resolve(ctx, req)
}

// UnsupportedKindError reports a source kind no registered kind can resolve.
//
// The manifest layer rejects a kind its grammar does not know, so reaching this
// means a kind harnaas parses but this binary cannot fetch — an older binary
// meeting a manifest written for a newer one. That is why the remedy is an
// upgrade rather than an edit, and why the error is a type: the install flow
// attributes it to the asset that carried the source.
type UnsupportedKindError struct {
	// Kind is the unresolvable kind, exactly as the manifest wrote it.
	Kind manifest.SourceKind

	// Registered is every kind this binary can resolve, sorted.
	Registered []manifest.SourceKind
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnsupportedKindError) Error() string {
	names := make([]string, 0, len(e.Registered))
	for _, name := range e.Registered {
		names = append(names, string(name))
	}

	return fmt.Sprintf(
		"this harnaas cannot resolve sources of kind %q\n\n"+
			"Upgrade harnaas, or declare a source of a kind it installs: %s.",
		e.Kind, strings.Join(names, ", "),
	)
}

// Package source turns a declared source into content harnaas can install.
//
// The manifest layer parses a source and resolves nothing: `github:acme/assets@v1`
// is checked for shape, and whether that repository exists, whether the ref
// points anywhere and what is at the path are all questions it deliberately does
// not ask. This package answers them, and it is the only place in harnaas that
// reaches the network or reads content out of a repository.
//
// Two things shape it. Every source kind answers the same question — given a
// parsed source and a path within it, produce the files and the provenance
// needed to record what landed — so the kinds sit behind one contract and a
// [Registry] dispatches to them by name. And a resolved source is worthless
// unless it can be re-identified later: `lint` has to answer "did somebody edit
// this?" and "has upstream moved?" independently, months after the install, from
// nothing but what was recorded. That is why a [Resolved] carries a digest per
// file and one over the source as a whole, and why the only way to obtain one is
// a constructor that computes both.
package source

import (
	"context"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Kind resolves the sources of one kind for one install run.
//
// It is created per run rather than registered as a value, because resolution is
// not stateless: a repository archive is fetched at most once per repository and
// commit per run, and the memory of what has already been fetched belongs to the
// run that did it. A kind shared across runs would either leak that memory
// between them or need a global cache to hold it.
type Kind interface {
	// Resolve produces the content and provenance for one asset's source.
	//
	// It is handed one asset rather than one `sources` entry because the unit
	// being resolved is the subtree an asset names, and because every diagnostic
	// raised here has to name the asset the author would go and edit.
	Resolve(ctx context.Context, req Request) (*Resolved, error)
}

// NewKind constructs a kind's resolver for one install run. It is what a kind
// registers, for the reason [Kind] gives.
type NewKind func(RunOptions) Kind

// RunOptions are the caller's choices for one resolution run.
//
// They are handed to every kind at construction rather than to [Kind.Resolve]
// per asset, because they describe the run and not the request: two assets of
// one install cannot disagree about whether the cache may be read.
type RunOptions struct {
	// Cache is where fetched content is reused from and kept for later runs. A
	// nil cache is the caller-facing bypass, and is deliberately the zero value:
	// a caller that has not said which cache to use has not said one may be
	// read, which is the answer that cannot surprise anybody.
	Cache *ArchiveCache

	// Offline is a run that must make no network request at all — not for
	// content, and not to ask a remote what a name points at. Every source is
	// satisfied from Cache and from what is already in the project, and one that
	// is in neither fails naming itself.
	//
	// Failing is the whole point. The alternatives an offline run could take —
	// skipping the asset, treating it as unchanged, or serving whatever content
	// this machine last happened to hold under that name — each turn a run that
	// could not do what it was asked into one that reports success, and the
	// third installs a different commit than the manifest declared.
	//
	// It is the zero value for the same reason a nil Cache is: a caller that has
	// not asked for an offline run has not said the network is unavailable, and
	// an offline run with no Cache can satisfy no remote source at all.
	Offline bool
}

// Request is one asset's resolution: the asset being resolved and the `sources`
// entry it references.
//
// The asset travels whole rather than as the two or three fields a kind reads,
// because the fields a diagnostic needs are not the fields resolution needs — a
// message names the asset's id and its position in the manifest, and narrowing
// the request would make every kind's errors worse to keep the struct smaller.
type Request struct {
	// Asset is the manifest entry being resolved, already interpreted: its
	// reference, type and id are settled before anything is fetched.
	Asset manifest.Asset

	// Source is the parsed `sources` entry the asset references. It is the zero
	// value for the project-local form, which references no entry.
	Source manifest.Source
}

// Kind reports which source kind must resolve this request.
//
// The project-local form declares no `sources` entry and is local by definition
// of the manifest grammar, not by anything a caller decides. Answering it here,
// once, is what keeps the install flow above and the kinds below from each
// restating that rule — and from restating it differently.
func (r Request) Kind() manifest.SourceKind {
	if r.Asset.Ref.Local() {
		return manifest.SourceKindLocal
	}
	return r.Source.Kind
}

// Package harness is harnaas's roster of the harnesses it recognizes.
//
// The roster is data only: an id, a display name, whether the harness has an
// unambiguous per-user location, and the observable evidence that a project is
// already using it. It maps nothing to a destination and it writes nothing. The
// adapters that turn an asset into a file on disk arrive with `harnaas install`
// and attach themselves to these ids.
//
// That seam is deliberate. Three things in this change need to know a harness
// exists — manifest validation must reject an unrecognized target, scope
// validation must know whether `user` scope has anywhere to go, and `init` must
// detect which harnesses a project already uses — while none of them needs to
// know where a skill lands. Deferring the roster until the adapters exist would
// force the manifest to accept any string as a harness name and reject it two
// phases later, at a point where the error can no longer name the line that
// caused it.
//
// A harness in the manifest's `harnesses` list is a guarantee, not an
// observation: it means "we guarantee the declared assets work for this
// harness". Because skills and instructions land in shared locations that
// several harnesses read, a harness absent from the list will still see assets
// installed for one that is present. That is why an unrecognized name is an
// error — it is a guarantee harnaas cannot make — and why an asset being
// visible to a harness nobody listed is not.
package harness

// ID is a harness's canonical identifier: the exact string a manifest writes in
// its `harnesses` list or an asset's `targets`, and the key an adapter will
// later register itself under.
//
// It is a named type rather than a bare string so a function taking a harness
// cannot silently be handed an asset id, a source key or a display name.
type ID string

// ClaudeCode is the only harness this change recognizes. More arrive with the
// adapters; the roster is where they are declared, one entry each.
const ClaudeCode ID = "claude-code"

// Default is the harness `harnaas init` scaffolds a manifest with when it
// detects none in the project. A default is what keeps init from ever writing
// an empty `harnesses` list, which would be a manifest that declares assets and
// guarantees them for nothing.
const Default = ClaudeCode

// Harness describes one recognized harness. Every field is data a caller reads;
// there is no behaviour here, and adding some is how the roster and the
// adapters start to disagree.
type Harness struct {
	// ID is the canonical identifier, and the only spelling a manifest may
	// use. Display names are never accepted as input.
	ID ID

	// DisplayName is what harnaas prints when it names the harness to a user.
	// It is never parsed, and never compared against manifest input.
	DisplayName string

	// PerUserLocation records whether the harness reads assets from an
	// unambiguous location in the user's home as well as from the project.
	//
	// This is what decides whether an asset may declare `user` scope for this
	// target. It is a property of the harness, not a preference: where a
	// harness has no single per-user root, or several that disagree, harnaas
	// has no correct answer and says so rather than guessing one.
	PerUserLocation bool

	// ProjectEvidence lists the project-root-relative paths whose presence
	// means the project is already using this harness. Any one of them is
	// enough.
	//
	// Evidence is observable state in the repository, never configuration the
	// user has not written yet: `init` runs before harnaas knows anything about
	// the project, so the only thing it can read is what the harness itself has
	// already left behind. The entries are paths rather than a predicate
	// because the roster stays data — `init` does the stat calls.
	ProjectEvidence []string
}

// roster is every recognized harness, ordered by ID.
//
// The order is the one callers see, so it has to be a property of the data
// rather than of how the literal happens to be written — a manifest error
// listing recognized harnesses must read identically on every run and every
// machine. TestRosterIsOrderedByID pins it, so an entry added in the wrong
// place fails a test instead of quietly reordering somebody's error message.
var roster = []Harness{
	{
		ID:              ClaudeCode,
		DisplayName:     "Claude Code",
		PerUserLocation: true,
		ProjectEvidence: []string{".claude", "CLAUDE.md"},
	},
}

package manifest

import (
	"fmt"
	"slices"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
)

// Scope is where an asset's installed copy lives: beside the project, or in the
// target harness's own per-user location.
//
// It is declared per asset rather than chosen per run because it is a property
// of the content — a team's house-style rule belongs to the repository, a
// personal shortcut belongs to the person — and a flag would make one manifest
// install to two different places depending on who ran the command.
type Scope string

const (
	// ScopeProject installs beneath the project root of each target harness. It
	// is the default, and the only scope an instruction may take.
	ScopeProject Scope = "project"

	// ScopeUser installs into the target harness's per-user location, and is
	// accepted only for a harness the roster records as having an unambiguous
	// one.
	ScopeUser Scope = "user"
)

// scopes is every accepted scope, in the order every diagnostic lists them —
// the default first, because it is the one an author reading the list most
// often wants.
var scopes = []Scope{ScopeProject, ScopeUser}

// Asset is one manifest entry with every question about it answered: what it
// is, what it is called, which harnesses it is guaranteed for, and where it
// installs.
//
// Nothing here is optional. Every field an entry may leave undeclared has been
// inferred from its path or defaulted from the document by the time an Asset
// exists, which is what makes it the shape later phases read: `install` never
// has to know whether the author wrote `type` or relied on the directory name,
// and so cannot treat the two differently.
type Asset struct {
	// Index is the entry's position in the `assets` array, carried through
	// because it stays the way every diagnostic points at the line to edit.
	Index int

	// ObjectForm records whether the entry was written as an object, so a
	// remedy can direct an author to the object form only when they are not
	// already using it.
	ObjectForm bool

	// Ref is the parsed source string: which source, and the path within it.
	Ref AssetRef

	// Type is the asset's type, declared or inferred from the containing
	// directory.
	Type AssetType

	// ID is the asset's id, declared or inferred from the path's leaf.
	ID string

	// Targets is the effective target list: the entry's own `targets` where it
	// declared them, and the manifest's `harnesses` otherwise. It is never
	// empty — an asset with no target could never be installed anywhere, which
	// is a violation rather than a state an Asset can reach.
	Targets []harness.ID

	// Scope is where the asset installs, `project` unless the entry declared
	// otherwise.
	Scope Scope
}

// ResolveType returns the entry's type: the one it declares, or the one its
// path implies.
//
// A declared type suppresses inference entirely rather than being checked
// against it. The object form exists precisely for a source whose layout does
// not follow the convention, so comparing the two would refuse the case it was
// added for.
func ResolveType(entry AssetEntry, ref AssetRef) (AssetType, *Violation) {
	if entry.Type == "" {
		return InferType(entry.Index, ref)
	}

	declared := AssetType(entry.Type)
	if !slices.Contains(AssetTypes(), declared) {
		return "", assetViolation(entry.Index, "type",
			fmt.Sprintf("%s declares the type %q, which is not a type harnaas installs", assetSubject(entry.Index), entry.Type),
			fmt.Sprintf("Set %q on the entry in %s to one of %s.", "type", FileName, typeList()),
		)
	}

	return declared, nil
}

// ResolveID returns the entry's id: the one it declares, or the one its path's
// leaf implies.
//
// Inference is suppressed one field at a time, which is why this is a separate
// decision from [ResolveType]: an entry declaring `type` for an unconventional
// layout still wants its id inferred, and an entry declaring `id` because two
// sources use the same leaf still wants its type inferred.
//
// Whether the resulting id is usable — a single safe path segment, unique among
// assets of its type — is a question about the document rather than the entry,
// and is answered where every entry's id is in hand.
func ResolveID(entry AssetEntry, ref AssetRef) (string, *Violation) {
	if entry.ID == "" {
		return InferID(entry.Index, ref)
	}
	return entry.ID, nil
}

// ResolveTargets returns the harnesses an entry is guaranteed for: its own
// `targets` where it declared them, and the manifest's `harnesses` otherwise.
//
// A name inherited from `harnesses` is not checked here. It is checked once by
// [CheckHarnesses], because a misspelling in that one list is one mistake, and
// attributing it to every asset that inherited it would report the same edit
// once per entry and bury the entries with problems of their own.
//
// The result is a list of violations rather than one because `targets` is
// itself a list: two unrecognized names are two independent edits, and each is
// attributed to its own position so the aggregate orders them the same way on
// every run.
func ResolveTargets(entry AssetEntry, harnesses []string) ([]harness.ID, []*Violation) {
	// A nil slice is an undeclared field and an empty one is a declared empty
	// list. Both leave the asset with nowhere to install, but the edit that
	// fixes them is different, so decoding kept them distinguishable and this
	// is where the distinction is spent.
	if entry.Targets == nil {
		if len(harnesses) == 0 {
			return nil, []*Violation{assetViolation(entry.Index, "targets",
				fmt.Sprintf(
					"%s has no target harness: it declares no %q and the manifest declares no %q",
					assetSubject(entry.Index), "targets", "harnesses",
				),
				fmt.Sprintf(
					"Add a %q list to %s naming at least one of %s, or declare %q on this entry.",
					"harnesses", FileName, harnessList(), "targets",
				),
			)}
		}
		return toHarnessIDs(harnesses), nil
	}

	if len(entry.Targets) == 0 {
		return nil, []*Violation{assetViolation(entry.Index, "targets",
			fmt.Sprintf(
				"%s declares an empty %q list, so it could never be installed anywhere",
				assetSubject(entry.Index), "targets",
			),
			fmt.Sprintf(
				"Name at least one of %s in the entry's %q, or remove the field so the asset inherits the manifest's %q.",
				harnessList(), "targets", "harnesses",
			),
		)}
	}

	var violations []*Violation
	targets := make([]harness.ID, 0, len(entry.Targets))
	for position, name := range entry.Targets {
		id := harness.ID(name)
		if !harness.Recognized(id) {
			violations = append(violations, assetViolation(entry.Index, fmt.Sprintf("targets[%d]", position),
				fmt.Sprintf(
					"%s targets %q, which is not a harness harnaas recognizes",
					assetSubject(entry.Index), name,
				),
				fmt.Sprintf("Change it in %s to a harness harnaas recognizes: %s.", FileName, harnessList()),
			))
			continue
		}
		targets = append(targets, id)
	}
	if len(violations) > 0 {
		return nil, violations
	}

	return targets, nil
}

// CheckHarnesses reports every name in the manifest's `harnesses` list the
// roster does not recognize.
//
// An empty list is not reported here. It is only a problem for an asset that
// would have inherited it, and an asset declaring its own `targets` is
// perfectly well served by a manifest that declares no default — so the
// violation belongs to the entry that has nowhere to go, not to the document.
func CheckHarnesses(harnesses []string) []*Violation {
	var violations []*Violation
	for position, name := range harnesses {
		if harness.Recognized(harness.ID(name)) {
			continue
		}

		violations = append(violations, &Violation{
			Index: DocumentIndex,
			Field: fmt.Sprintf("harnesses[%d]", position),
			Problem: fmt.Sprintf(
				"the %q list names %q, which is not a harness harnaas recognizes",
				"harnesses", name,
			),
			Fix: fmt.Sprintf("Change it in %s to a harness harnaas recognizes: %s.", FileName, harnessList()),
		})
	}
	return violations
}

// ResolveScope returns where the entry installs: the scope it declares, or
// `project`.
func ResolveScope(entry AssetEntry, assetType AssetType, targets []harness.ID) (Scope, *Violation) {
	return resolveScope(entry, assetType, targets, harness.HasPerUserLocation)
}

// resolveScope is [ResolveScope] with the roster query as a parameter.
//
// The seam exists because the roster is data this package cannot vary: today
// every recognized harness has a per-user location, so the rule that `user`
// scope is refused where one does not exist would have no test at all, and
// would be free to rot until the first harness that lacks one is added — which
// is exactly when a silent fall back to project scope would start installing
// assets somewhere nobody asked for.
func resolveScope(
	entry AssetEntry,
	assetType AssetType,
	targets []harness.ID,
	perUserLocation func(harness.ID) (bool, error),
) (Scope, *Violation) {
	if entry.Scope == "" {
		return ScopeProject, nil
	}

	declared := Scope(entry.Scope)
	if !slices.Contains(scopes, declared) {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf("%s declares the scope %q, which harnaas does not define", assetSubject(entry.Index), entry.Scope),
			fmt.Sprintf(
				"Set %q on the entry in %s to one of %s, or remove it to install at %q scope.",
				"scope", FileName, scopeList(), ScopeProject,
			),
		)
	}
	if declared == ScopeProject {
		return ScopeProject, nil
	}

	// An instruction is guidance concatenated into a committed memory file, and
	// what distinguishes it from a rule is surviving a fresh clone inside that
	// file. At user scope there is no clone and no committed file, so the type
	// would mean nothing — this is definitional, not a limitation of the
	// installer.
	if assetType == AssetTypeInstruction {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf(
				"%s is an %s at %q scope, and an %s exists only inside the project's committed memory file",
				assetSubject(entry.Index), AssetTypeInstruction, ScopeUser, AssetTypeInstruction,
			),
			fmt.Sprintf(
				"Remove %q from the entry in %s, or declare its %q as %q, which is the type for always-on guidance outside a committed file.",
				"scope", FileName, "type", AssetTypeRule,
			),
		)
	}

	var unsupported []string
	for _, target := range targets {
		hasLocation, err := perUserLocation(target)
		if err != nil {
			// The target is not in the roster, which [ResolveTargets] or
			// [CheckHarnesses] has already reported against the field that
			// declared it. Reporting it a second time as a scope problem would
			// name an edit that does not fix it.
			continue
		}
		if !hasLocation {
			unsupported = append(unsupported, quoted(string(target)))
		}
	}

	if len(unsupported) > 0 {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf(
				"%s declares %q scope, and %s no unambiguous per-user location",
				assetSubject(entry.Index), ScopeUser, hasNo(unsupported),
			),
			fmt.Sprintf(
				"Remove %q from the entry in %s so it installs at %q scope, or narrow the entry's %q to harnesses with a per-user location.",
				"scope", FileName, ScopeProject, "targets",
			),
		)
	}

	return ScopeUser, nil
}

// toHarnessIDs converts a declared name list into roster ids. It is only ever
// called with names already checked against the roster, or with the manifest's
// `harnesses` list, whose names [CheckHarnesses] reports on separately.
func toHarnessIDs(names []string) []harness.ID {
	ids := make([]harness.ID, 0, len(names))
	for _, name := range names {
		ids = append(ids, harness.ID(name))
	}
	return ids
}

// hasNo renders the offending targets as the subject of a sentence, so one
// target reads as naturally as several.
func hasNo(targets []string) string {
	if len(targets) == 1 {
		return "the target " + targets[0] + " has"
	}
	return "the targets " + strings.Join(targets, ", ") + " have"
}

// typeList renders every asset type for a diagnostic, in the fixed order
// [AssetTypes] gives.
func typeList() string {
	names := make([]string, 0, len(AssetTypes()))
	for _, assetType := range AssetTypes() {
		names = append(names, quoted(string(assetType)))
	}
	return strings.Join(names, ", ")
}

// scopeList renders every accepted scope for a diagnostic.
func scopeList() string {
	names := make([]string, 0, len(scopes))
	for _, scope := range scopes {
		names = append(names, quoted(string(scope)))
	}
	return strings.Join(names, ", ")
}

// harnessList renders every recognized harness id for a diagnostic, in the
// roster's own order so two runs produce the same sentence.
func harnessList() string {
	ids := harness.IDs()
	names := make([]string, 0, len(ids))
	for _, id := range ids {
		names = append(names, quoted(string(id)))
	}
	return strings.Join(names, ", ")
}

package cli

import (
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
)

// harnessOrigin records how init arrived at a harness selection.
//
// The three origins are kept apart because each owes the user a different
// sentence: a flag-supplied list needs no explanation, a detected one is worth
// stating so a wrong guess is visible, and the default is the only case where
// harnaas chose a harness the project shows no sign of using.
type harnessOrigin int

const (
	// originFlag means the user named the harnesses explicitly.
	originFlag harnessOrigin = iota
	// originDetected means the project's own contents named them.
	originDetected
	// originDefault means nothing was detected and the roster's default was
	// used, because a manifest with an empty `harnesses` list would declare
	// assets and guarantee them for nothing.
	originDefault
)

// harnessSelection is the target list a scaffolded manifest will declare,
// together with how it was arrived at.
type harnessSelection struct {
	// Harnesses is the selection in the order it will be written, with
	// duplicates removed.
	Harnesses []harness.ID

	// Origin is how the list was arrived at.
	Origin harnessOrigin
}

// selectHarnesses resolves the manifest's `harnesses` list from what the user
// asked for and, failing that, from what the project shows.
//
// A flag-supplied list replaces detection entirely rather than adding to it.
// Merging the two would make the manifest depend on what happened to be in the
// working tree at the moment init ran, which is the opposite of what naming the
// harnesses explicitly asks for — and it would leave no way to scaffold a
// manifest that omits a harness the project already contains.
func selectHarnesses(root string, requested []string) (harnessSelection, error) {
	if len(requested) > 0 {
		ids, err := recognizedHarnesses(requested)
		if err != nil {
			return harnessSelection{}, err
		}
		return harnessSelection{Harnesses: ids, Origin: originFlag}, nil
	}

	if detected := detectHarnesses(root, harness.All()); len(detected) > 0 {
		return harnessSelection{Harnesses: detected, Origin: originDetected}, nil
	}

	return harnessSelection{Harnesses: []harness.ID{harness.Default}, Origin: originDefault}, nil
}

// recognizedHarnesses turns the flag's raw strings into roster ids, failing on
// the first name harnaas does not recognize.
//
// The roster's own error is returned unwrapped: it already names the input and
// lists what harnaas does recognize, which is the whole diagnostic, and the user
// is looking at the flag they just typed.
//
// A name repeated across flag occurrences is kept once. The manifest is a
// declaration rather than a log of what was typed, and a `harnesses` list naming
// one harness twice would be a file harnaas asked its author to hand-edit and
// then wrote badly itself.
func recognizedHarnesses(names []string) ([]harness.ID, error) {
	ids := make([]harness.ID, 0, len(names))
	for _, name := range names {
		id := harness.ID(name)
		if _, err := harness.Lookup(id); err != nil {
			return nil, err
		}
		if !slices.Contains(ids, id) {
			ids = append(ids, id)
		}
	}
	return ids, nil
}

// detectHarnesses reports which recognized harnesses the project already shows
// evidence of, in the roster's order.
//
// Detection reads and creates nothing: it stats the paths the roster declares as
// evidence and nothing else. That matters more here than it looks, because init
// runs before the project is under harnaas management at all — a detection pass
// that created a directory to look inside would be the one file init is
// forbidden to write.
//
// Order is the roster's rather than the filesystem's, so two projects containing
// the same harnesses scaffold the same list. The roster is a parameter for that
// clause alone: claude-code is the only entry today, so "every detected harness
// appears, in a deterministic order" has no case that exercises it, and the rule
// has to hold before the second harness is added rather than after.
func detectHarnesses(root string, roster []harness.Harness) []harness.ID {
	var detected []harness.ID
	for _, h := range roster {
		if usesHarness(root, h) {
			detected = append(detected, h.ID)
		}
	}
	return detected
}

// usesHarness reports whether any one of a harness's evidence paths exists in
// the project. Any single piece of evidence is enough — a project with a
// `CLAUDE.md` and no `.claude/` is still a project using Claude Code.
//
// The check is an Lstat rather than a Stat because the question is whether the
// harness left something behind, not whether that something resolves: a symlink
// named `.claude` pointing at a directory that is not checked out is still
// evidence, and following it would answer "no" for a project that plainly says
// yes.
func usesHarness(root string, h harness.Harness) bool {
	for _, evidence := range h.ProjectEvidence {
		if _, err := os.Lstat(filepath.Join(root, evidence)); err == nil {
			return true
		}
	}
	return false
}

// displayNames renders a selection the way it is said to a person, using the
// roster's display names rather than the ids the manifest will hold.
//
// An id that is somehow not on the roster falls back to itself rather than
// dropping out of the sentence: a selection is only ever built from recognized
// ids, and a message that silently listed fewer harnesses than it was about
// would be worse than one naming a raw id.
func displayNames(ids []harness.ID) string {
	names := make([]string, 0, len(ids))
	for _, id := range ids {
		h, err := harness.Lookup(id)
		if err != nil {
			names = append(names, string(id))
			continue
		}
		names = append(names, h.DisplayName)
	}
	return strings.Join(names, ", ")
}

package source

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Every diagnostic here is about content that arrived intact and is not what the
// asset said it was, so none of them names a host, a commit or a credential.
// What each one names is the asset, because the edit that fixes it is in
// `harnaas.json` or in the source the entry points at, and a reader who has both
// open needs to know which entry to look at first.

// ShapeError reports content whose shape is not the one its asset type requires.
//
// The expected and the found shape are both carried as text rather than derived
// from the type at render time, because the two halves of the sentence come from
// two different places — the type's rule, and the directory somebody is looking
// at — and a message that restated the rule twice would leave the reader to work
// out which half was the observation.
type ShapeError struct {
	// AssetID is the asset whose source was verified.
	AssetID string

	// Type is the asset's type, which is where the requirement comes from.
	Type manifest.AssetType

	// Expected is the shape the type requires, in the words the message uses.
	Expected string

	// Found is what the source resolved to instead.
	Found string
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *ShapeError) Error() string {
	return fmt.Sprintf(
		"the asset %q is a %s, which must be %s, and its source is %s\n\n"+
			"Point the entry at %s, or change the entry's %q in %s to match what the source is.",
		e.AssetID, e.Type, e.Expected, e.Found,
		e.Expected, "type", manifest.FileName,
	)
}

// MissingSkillFileError reports a skill directory with no SKILL.md in it.
//
// It is separate from [ShapeError] because the source is the right shape and the
// edit is in the content rather than in the manifest: adding a file, or pointing
// the entry one directory deeper. Reporting it as a shape mismatch would send an
// author to change a `type` that is correct.
type MissingSkillFileError struct {
	// AssetID is the asset whose source was verified.
	AssetID string

	// Source is the path the entry declared, as the manifest spells it.
	Source string
}

package source_test

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// recordingKind is a kind that resolves nothing and remembers whether it was
// asked to. What most of these tests assert is which kind was reached, and — for
// an unsupported kind — that none was.
type recordingKind struct {
	calls []source.Request
}

func (k *recordingKind) Resolve(_ context.Context, req source.Request) (*source.Resolved, error) {
	k.calls = append(k.calls, req)
	return source.NewResolved(source.Provenance{Kind: req.Kind()}, map[string][]byte{
		"SKILL.md": []byte(req.Asset.ID),
	})
}

// remoteAssetID is the id every keyed-form request in these tests carries. The
// tests that vary an id vary the local form's, because a request's kind is the
// only thing under test here.
const remoteAssetID = "review"

// githubRequest is one asset resolved through a `sources` entry.
func githubRequest() source.Request {
	return source.Request{
		Asset: manifest.Asset{
			Ref:  manifest.AssetRef{SourceKey: "acme", Path: "skills/" + remoteAssetID},
			Type: manifest.AssetTypeSkill,
			ID:   remoteAssetID,
		},
		Source: manifest.Source{
			Key:        "acme",
			Kind:       manifest.SourceKindGitHub,
			Repository: "acme/assets",
			Ref:        "v1.2.0",
		},
	}
}

// localRequest is one asset resolved from the project's own `.harnaas`, which
// references no `sources` entry at all.
func localRequest(id string) source.Request {
	return source.Request{
		Asset: manifest.Asset{
			Ref:  manifest.AssetRef{Path: manifest.LocalRoot + "/skills/" + id},
			Type: manifest.AssetTypeSkill,
			ID:   id,
		},
	}
}

func TestResolverDispatchesToTheKindThatOwnsTheSource(t *testing.T) {
	t.Parallel()

	github, local := &recordingKind{}, &recordingKind{}
	registry := registryWith(t, map[manifest.SourceKind]source.Kind{
		manifest.SourceKindGitHub: github,
		manifest.SourceKindLocal:  local,
	})

	resolver := registry.NewResolver(source.RunOptions{})

	remote, err := resolver.Resolve(t.Context(), githubRequest())
	require.NoError(t, err)
	assert.Equal(t, manifest.SourceKindGitHub, remote.Provenance.Kind)

	own, err := resolver.Resolve(t.Context(), localRequest("house-style"))
	require.NoError(t, err)
	assert.Equal(t, manifest.SourceKindLocal, own.Provenance.Kind)

	require.Len(t, github.calls, 1)
	assert.Equal(t, remoteAssetID, github.calls[0].Asset.ID)
	require.Len(t, local.calls, 1)
	assert.Equal(t, "house-style", local.calls[0].Asset.ID)
}

// TestUnregisteredKindFailsBeforeAnyKindIsAsked is the dispatch half of "no
// network request or filesystem write occurs": the lookup precedes the work, so
// the registered kind is never entered.
func TestUnregisteredKindFailsBeforeAnyKindIsAsked(t *testing.T) {
	t.Parallel()

	local := &recordingKind{}
	registry := registryWith(t, map[manifest.SourceKind]source.Kind{
		manifest.SourceKindLocal: local,
	})

	resolved, err := registry.NewResolver(source.RunOptions{}).Resolve(t.Context(), githubRequest())

	require.Error(t, err)
	assert.Nil(t, resolved)
	assert.Empty(t, local.calls)

	var unsupported *source.UnsupportedKindError
	require.ErrorAs(t, err, &unsupported)
	assert.Equal(t, manifest.SourceKindGitHub, unsupported.Kind)
	assert.Equal(t, []manifest.SourceKind{manifest.SourceKindLocal}, unsupported.Registered)
}

func TestUnsupportedKindErrorStatesTheProblemThenTheFix(t *testing.T) {
	t.Parallel()

	err := &source.UnsupportedKindError{
		Kind:       "gitlab",
		Registered: []manifest.SourceKind{manifest.SourceKindGitHub, manifest.SourceKindLocal},
	}

	problem, fix, found := strings.Cut(err.Error(), "\n\n")
	require.True(t, found, "the message separates the problem from the fix")
	assert.Contains(t, problem, `"gitlab"`)
	assert.NotContains(t, problem, "\n")
	assert.Contains(t, fix, "github, local")
}

// TestUnsupportedKindErrorListsWhatThisRunCouldResolve pins the captured list:
// the message stays a complete diagnostic wherever it is finally printed, rather
// than describing the registry as it stands when somebody reads it.
func TestUnsupportedKindErrorListsWhatThisRunCouldResolve(t *testing.T) {
	t.Parallel()

	registry := registryWith(t, map[manifest.SourceKind]source.Kind{
		manifest.SourceKindLocal: &recordingKind{},
	})
	resolver := registry.NewResolver(source.RunOptions{})

	registry.Register(manifest.SourceKindGitHub, func(source.RunOptions) source.Kind { return &recordingKind{} })

	_, err := resolver.Resolve(t.Context(), githubRequest())

	var unsupported *source.UnsupportedKindError
	require.ErrorAs(t, err, &unsupported)
	assert.Equal(t, []manifest.SourceKind{manifest.SourceKindLocal}, unsupported.Registered)
}

func TestRegisterPanicsOnADuplicateKind(t *testing.T) {
	t.Parallel()

	registry := registryWith(t, map[manifest.SourceKind]source.Kind{
		manifest.SourceKindLocal: &recordingKind{},
	})

	assert.PanicsWithValue(t, `source: kind "local" is registered twice`, func() {
		registry.Register(manifest.SourceKindLocal, func(source.RunOptions) source.Kind { return &recordingKind{} })
	})
}

// TestKindsIsSortedRatherThanInRegistrationOrder matters because registration
// order is whatever the import graph produces, and this list is rendered into a
// message a user reads.
func TestKindsIsSortedRatherThanInRegistrationOrder(t *testing.T) {
	t.Parallel()

	var registry source.Registry
	for _, name := range []manifest.SourceKind{"local", "github", "acme"} {
		registry.Register(name, func(source.RunOptions) source.Kind { return &recordingKind{} })
	}

	sorted := []manifest.SourceKind{"acme", "github", "local"}
	assert.Equal(t, sorted, registry.Kinds())
	assert.Equal(t, sorted, registry.Kinds(), "and the same list on every call")
}

func TestKindsOfAnEmptyRegistryIsEmpty(t *testing.T) {
	t.Parallel()

	var registry source.Registry
	assert.Empty(t, registry.Kinds())
}

// TestEachRunGetsItsOwnKind is the reason registration takes a constructor: what
// a kind remembers — which archives this run has already fetched — must not
// outlive the run that learned it.
func TestEachRunGetsItsOwnKind(t *testing.T) {
	t.Parallel()

	constructed := 0
	var registry source.Registry
	registry.Register(manifest.SourceKindLocal, func(source.RunOptions) source.Kind {
		constructed++
		return &recordingKind{}
	})

	assert.Equal(t, 0, constructed, "no kind is constructed until a run needs one")

	first, second := registry.NewResolver(source.RunOptions{}), registry.NewResolver(source.RunOptions{})
	assert.Equal(t, 2, constructed)

	_, err := first.Resolve(t.Context(), localRequest("one"))
	require.NoError(t, err)
	_, err = second.Resolve(t.Context(), localRequest("two"))
	require.NoError(t, err)
}

// TestTheRunsOptionsReachEveryKind is why the options are settled at the
// resolver rather than at each kind's own entry point: a run cannot end up with
// one kind reading the cache and another bypassing it.
func TestTheRunsOptionsReachEveryKind(t *testing.T) {
	t.Parallel()

	var given []source.RunOptions
	var registry source.Registry
	for _, name := range []manifest.SourceKind{manifest.SourceKindGitHub, manifest.SourceKindLocal} {
		registry.Register(name, func(opts source.RunOptions) source.Kind {
			given = append(given, opts)
			return &recordingKind{}
		})
	}

	opts := source.RunOptions{Cache: source.NewArchiveCache(), Offline: true}
	registry.NewResolver(opts)

	require.Len(t, given, 2)
	for _, got := range given {
		assert.Same(t, opts.Cache, got.Cache)
		assert.True(t, got.Offline, "a run is offline for every kind or for none; the network is not per kind")
	}
}

// TestResolveReportsTheKindsOwnFailure keeps dispatch transparent: a kind's error
// reaches the caller as it was written, because it is the one that can name the
// repository, the ref and the asset.
func TestResolveReportsTheKindsOwnFailure(t *testing.T) {
	t.Parallel()

	sentinel := errors.New("the remote refused the connection")

	var registry source.Registry
	registry.Register(manifest.SourceKindLocal, func(source.RunOptions) source.Kind {
		return failingKind{err: sentinel}
	})

	resolved, err := registry.NewResolver(source.RunOptions{}).Resolve(t.Context(), localRequest("one"))

	require.ErrorIs(t, err, sentinel)
	assert.Nil(t, resolved)
}

type failingKind struct{ err error }

func (k failingKind) Resolve(context.Context, source.Request) (*source.Resolved, error) {
	return nil, k.err
}

// registryWith builds a registry holding the given kinds, each handed back to
// every run rather than constructed fresh, so a test can hold on to the instance
// it wants to make assertions about.
func registryWith(tb testing.TB, kinds map[manifest.SourceKind]source.Kind) *source.Registry {
	tb.Helper()

	registry := &source.Registry{}
	for name, kind := range kinds {
		registry.Register(name, func(source.RunOptions) source.Kind { return kind })
	}
	return registry
}

